                <p>Entradas</p>
                <?php
                $lista_butacas = explode(",", $butacas);
                foreach ($lista_butacas as $b) {
                    if (preg_match('/F(\d+)-B(\d+)/', $b, $matches)) {
                        $fila = $matches[1];
                        $num = $matches[2];
                        echo "<p>Sala  $sala  Fila  $fila  Butaca  $num</p>";
                    }
                }
                echo "<p class='total'> Total " . $subtotal . " €";
                ?>
